import { ArrowRight, CheckCircle2, CircleHelp, UsersRound } from "lucide-react";
import { Link } from "react-router-dom";
import { PageHeader } from "../components/content/page-elements";
import { Accordion, AccordionContent, AccordionItem, AccordionTrigger } from "../components/ui/accordion";
import { Button } from "../components/ui/button";
import { clubSettings, departments, faqs } from "../data/site-data";

export function JoinPage() {
  const statusText = clubSettings.recruitmentStatus === "open" ? "VIC đang mở đợt tuyển thành viên." : clubSettings.recruitmentStatus === "closed" ? "Đợt tuyển hiện đã đóng." : "Thông tin tuyển thành viên sẽ được cập nhật qua các kênh chính thức của VIC.";
  const canApply = clubSettings.recruitmentStatus === "open" && Boolean(clubSettings.applicationUrl);
  return <main id="main"><PageHeader eyebrow="THAM GIA VIC" title={<>Bạn không cần biết hết.<br />Chỉ cần muốn bắt đầu.</>} description="Nếu bạn thích công nghệ, muốn thử một điều mới hoặc tìm những người cùng học, VIC có thể là nơi để bạn bắt đầu.">{canApply && <Button asChild><a href={clubSettings.applicationUrl!}>Gửi đăng ký <ArrowRight size={17} /></a></Button>}</PageHeader>
    <section className="section-space"><div className="page-container"><div className="grid gap-5 md:grid-cols-3">{[{ icon: UsersRound, title: "Bạn đồng hành", text: "Kết nối với những người cũng đang học, thử và hoàn thiện kỹ năng." }, { icon: CheckCircle2, title: "Trải nghiệm thực hành", text: "Tham gia những hoạt động và sản phẩm phù hợp với khả năng hiện tại." }, { icon: CircleHelp, title: "Không gian đặt câu hỏi", text: "Bắt đầu từ điều chưa rõ và cùng nhau tìm cách giải quyết." }].map(({ icon: Icon, title, text }) => <article key={title} className="glass-surface rounded-[2rem] p-7"><Icon className="text-vic-blue" /><h2 className="mt-8 text-xl font-semibold">{title}</h2><p className="mt-3 text-sm leading-7 text-vic-muted">{text}</p></article>)}</div></div></section>
    <section className="section-space bg-vic-surface"><div className="page-container"><p className="section-label">02 / CHỌN KHÔNG GIAN</p><div className="grid gap-6 md:grid-cols-2">{departments.map((department) => <Link key={department.id} to={`/${department.slug}`} className="interactive-card rounded-[2rem] bg-white p-8"><h2 className="text-2xl font-semibold">{department.name}</h2><p className="mt-3 leading-7 text-vic-muted">{department.summary}</p><span className="mt-6 inline-flex items-center gap-2 font-semibold text-vic-blue">Tìm hiểu ban <ArrowRight size={16} /></span></Link>)}</div></div></section>
    <section className="section-space"><div className="page-container grid gap-12 lg:grid-cols-[.8fr_1.2fr]"><div><p className="section-label">03 / CÁC BƯỚC</p><h2 className="section-title">Từ tìm hiểu đến kết nối.</h2></div><ol className="space-y-4">{["Tìm hiểu VIC và hai ban.", "Theo dõi thông tin khi VIC mở đợt tuyển.", "Gửi đăng ký qua biểu mẫu chính thức nếu có.", "Kết nối và tham gia hoạt động phù hợp."].map((step, index) => <li key={step} className="grid grid-cols-[2.75rem_1fr] items-center gap-4 border-b border-black/10 pb-4"><span className="font-mono text-sm font-semibold text-vic-blue">0{index + 1}</span><span>{step}</span></li>)}</ol></div></section>
    <section className="section-space bg-vic-ink text-white"><div className="page-container grid gap-10 lg:grid-cols-2"><div><p className="font-mono text-xs font-semibold text-[#8ea8ff]">TRẠNG THÁI TUYỂN THÀNH VIÊN</p><h2 className="mt-5 text-3xl font-bold tracking-[-.04em]">{statusText}</h2><p className="mt-4 text-sm leading-7 text-white/60">Website chưa thu thập dữ liệu cá nhân. Nút đăng ký chỉ xuất hiện khi trạng thái mở và có URL biểu mẫu hợp lệ.</p></div><div><p className="mb-4 font-mono text-xs font-semibold text-[#8ea8ff]">KÊNH LIÊN HỆ</p><p className="text-white/65">Facebook và email chính thức chưa được cung cấp. Các liên kết sẽ xuất hiện tại đây khi được xác nhận.</p></div></div></section>
    <section className="section-space"><div className="page-container grid gap-12 lg:grid-cols-[.7fr_1.3fr]"><div><p className="section-label">04 / FAQ</p><h2 className="section-title">Một vài điều bạn có thể đang hỏi.</h2></div><Accordion type="single" collapsible className="border-t border-black/10">{faqs.map((item) => <AccordionItem key={item.id} value={item.id}><AccordionTrigger>{item.question}</AccordionTrigger><AccordionContent>{item.answer}</AccordionContent></AccordionItem>)}</Accordion></div></section>
  </main>;
}
